"use client"

import React from 'react'
import Link from 'next/link'
import Image from 'next/image'
import { motion } from 'framer-motion'
import { Shield, Sword, Users, Calendar, MapPin, Award, ArrowRight } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Countdown } from '@/components/ui/countdown'
import { CardSpotlight } from '@/components/ui/card-spotlight'
import { ShinyText } from '@/components/ui/shiny-text'
import { GlareCard } from '@/components/ui/glare-card'
import { MagneticElement } from '@/components/ui/magnetic-element'
import { SplitText } from '@/components/ui/split-text'
import { BentoGrid, BentoCard } from '@/components/ui/magic-bento'
import { appConfig } from '@/lib/config'
import { isRevealed } from '@/lib/utils'

export default function Session3Page() {
  const { event, reveals, venue, forms } = appConfig

  return (
    <div className="min-h-screen">
      {/* Hero Section */}
      <section className="relative min-h-screen flex items-center justify-center overflow-hidden">
        {/* Sophisticated Background */}
        <div className="absolute inset-0 bg-gradient-to-br from-background via-forest-950/40 to-background" />
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_30%_50%,rgba(198,168,88,0.08),transparent_60%)]" />
        <div className="absolute inset-0 bg-[linear-gradient(to_right,transparent_0%,rgba(198,168,88,0.02)_50%,transparent_100%)]" />
        
        {/* Elegant Grid Pattern */}
        <div className="absolute inset-0 opacity-[0.015]" style={{backgroundImage: 'radial-gradient(circle, #c6a858 1px, transparent 1px)', backgroundSize: '50px 50px'}} />
        
        {/* Subtle Corner Accents */}
        <div className="absolute inset-0 overflow-hidden pointer-events-none">
          <div className="absolute top-0 left-0 w-96 h-96 bg-gradient-to-br from-accent-gold/5 to-transparent rounded-full blur-3xl" />
          <div className="absolute bottom-0 right-0 w-96 h-96 bg-gradient-to-tl from-forest-600/10 to-transparent rounded-full blur-3xl" />
        </div>

        <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
          <motion.div
            initial={{ opacity: 0, y: 50 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 1 }}
            className="space-y-12"
          >
            {/* Refined Badge */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6, delay: 0.2 }}
              className="inline-flex items-center justify-center"
            >
              <div className="px-6 py-2 bg-gradient-to-r from-accent-gold/10 via-accent-gold/5 to-accent-gold/10 border border-accent-gold/20 rounded-full backdrop-blur-sm">
                <span className="text-accent-gold text-sm font-semibold tracking-wider">IGACMUN SESSION III</span>
              </div>
            </motion.div>

            {/* Main Title */}
            <div className="space-y-6">
              <motion.h1
                initial={{ opacity: 0, y: 30 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.8, delay: 0.4 }}
                className="font-display text-5xl md:text-7xl lg:text-8xl font-bold text-foreground leading-tight"
              >
                <ShinyText className="text-foreground">{event.subtitle}</ShinyText>
              </motion.h1>
              <motion.p
                initial={{ opacity: 0, y: 30 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.8, delay: 0.7 }}
                className="text-2xl md:text-3xl text-accent-gold font-display"
              >
                {event.tagline}
              </motion.p>
              <motion.p
                initial={{ opacity: 0, y: 30 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.8, delay: 0.9 }}
                className="text-lg md:text-xl text-muted-foreground max-w-4xl mx-auto leading-relaxed"
              >
                {event.description}
              </motion.p>
            </div>

            {/* CTA Section */}
            <motion.div
              initial={{ opacity: 0, y: 30 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.8, delay: 1.1 }}
              className="flex flex-col sm:flex-row gap-6 justify-center items-center"
            >
              <MagneticElement strength={0.2}>
                <Button variant="thorn" size="xl" asChild>
                  <Link href="/session-3/register" className="group">
                    Register Now
                    <ArrowRight className="ml-2 h-5 w-5 group-hover:translate-x-1 transition-transform" />
                  </Link>
                </Button>
              </MagneticElement>
              <MagneticElement strength={0.2}>
                <Button variant="outline" size="xl" asChild>
                  <Link href="/session-3/committees">
                    View Committees
                  </Link>
                </Button>
              </MagneticElement>
            </motion.div>
          </motion.div>
        </div>
      </section>

      {/* Conference Overview - Split Layout */}
      <section className="py-32 relative overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-b from-background to-forest-950/50" />
        
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 items-center">
            {/* Left: Content */}
            <motion.div
              initial={{ opacity: 0, x: -50 }}
              whileInView={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.8 }}
              viewport={{ once: true }}
              className="space-y-8"
            >
              <div>
                <div className="inline-block px-4 py-2 bg-accent-gold/10 border border-accent-gold/30 rounded-full mb-6">
                  <span className="text-accent-gold font-semibold text-sm tracking-wider">CONFERENCE OVERVIEW</span>
                </div>
                <h2 className="font-display text-4xl md:text-5xl font-bold text-foreground mb-6">
                  South East Asia's Premier MUN Conference
                </h2>
                <p className="text-lg text-muted-foreground leading-relaxed mb-8">
                  IGACMUN Session III brings together over 1700+ delegates from across the region for an unparalleled diplomatic experience. Engage in high-stakes negotiations, develop critical leadership skills, and be part of shaping tomorrow's global discourse.
                </p>
              </div>
              
              <div className="grid grid-cols-2 gap-6">
                {[
                  { number: "1700+", label: "Expected Delegates" },
                  { number: "10", label: "Committees" },
                  { number: "3", label: "Conference Days" },
                  { number: "100+", label: "Partner Institutions" }
                ].map((stat, index) => (
                  <motion.div
                    key={stat.label}
                    initial={{ opacity: 0, y: 20 }}
                    whileInView={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.5, delay: 0.2 + index * 0.1 }}
                    viewport={{ once: true }}
                    className="text-center p-6 bg-gradient-to-br from-card to-forest-900/20 border border-accent-gold/20 rounded-xl"
                  >
                    <div className="text-3xl font-bold text-accent-gold mb-2">{stat.number}</div>
                    <div className="text-sm text-muted-foreground">{stat.label}</div>
                  </motion.div>
                ))}
              </div>
            </motion.div>

            {/* Right: Image + Features */}
            <motion.div
              initial={{ opacity: 0, x: 50 }}
              whileInView={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.8 }}
              viewport={{ once: true }}
              className="space-y-6"
            >
              <div className="relative h-96 rounded-2xl overflow-hidden border-2 border-accent-gold/30">
                <Image
                  src="/events/igacmun.jpg"
                  alt="IGACMUN Conference"
                  fill
                  className="object-cover"
                  sizes="(max-width: 1024px) 100vw, 50vw"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-forest-900/80 to-transparent" />
                <div className="absolute bottom-6 left-6 right-6">
                  <div className="bg-forest-900/60 backdrop-blur-md border border-accent-gold/30 rounded-xl p-4">
                    <div className="text-accent-gold font-semibold mb-1">December 19-21, 2025</div>
                    <div className="text-foreground text-sm">American International University-Bangladesh</div>
                  </div>
                </div>
              </div>
              
              <div className="grid grid-cols-1 gap-4">
                {[
                  { icon: Award, text: "Prestigious Awards & Recognition" },
                  { icon: Shield, text: "Professional Standards & Protocol" },
                  { icon: Users, text: "Network with Regional Leaders" }
                ].map((item, index) => (
                  <motion.div
                    key={item.text}
                    initial={{ opacity: 0, x: 20 }}
                    whileInView={{ opacity: 1, x: 0 }}
                    transition={{ duration: 0.5, delay: 0.3 + index * 0.1 }}
                    viewport={{ once: true }}
                    className="flex items-center space-x-4 p-4 bg-card border border-accent-gold/20 rounded-xl"
                  >
                    <div className="p-3 bg-accent-gold/10 rounded-lg">
                      <item.icon className="h-5 w-5 text-accent-gold" />
                    </div>
                    <span className="text-foreground font-medium">{item.text}</span>
                  </motion.div>
                ))}
              </div>
            </motion.div>
          </div>
        </div>
      </section>

      {/* Config-Driven Callouts */}
      <section className="py-24 bg-gradient-to-b from-background to-forest-950/30 relative">
        {/* Background pattern */}
        <div className="absolute inset-0 opacity-5">
          <div className="absolute top-20 left-10 w-72 h-72 bg-accent-gold/20 rounded-full blur-3xl" />
          <div className="absolute bottom-20 right-10 w-96 h-96 bg-forest-600/20 rounded-full blur-3xl" />
        </div>
        
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
          {/* Section Header */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            viewport={{ once: true }}
            className="text-center mb-16"
          >
            <h2 className="font-display text-4xl md:text-5xl font-bold text-foreground mb-4">
              Conference Details
            </h2>
            <div className="w-24 h-1 bg-gradient-to-r from-transparent via-accent-gold to-transparent mx-auto" />
          </motion.div>

          <BentoGrid className="lg:grid-cols-2 gap-6">
            {/* Committees */}
            <BentoCard index={0} className="p-8">
              <div className="flex items-center mb-6">
                <div className="p-3 bg-gradient-to-br from-accent-gold/20 to-accent-gold/10 rounded-xl mr-4">
                  <Users className="h-6 w-6 text-accent-gold" />
                </div>
                <div>
                  <h3 className="font-display text-2xl font-bold text-foreground">
                    Committees
                  </h3>
                  <p className="text-sm text-muted-foreground">Diplomatic arenas</p>
                </div>
              </div>
              
              {!isRevealed(reveals.committees.revealAt) ? (
                <div className="text-center py-8">
                  <Countdown
                    revealAt={reveals.committees.revealAt}
                    title="Coming Soon"
                    description="Committee details will be announced"
                  />
                </div>
              ) : (
                <div className="space-y-4">
                  <p className="text-muted-foreground">
                    Explore our diverse range of committees covering global issues and diplomatic challenges.
                  </p>
                  <Button variant="outline" asChild>
                    <Link href="/session-3/committees">
                      View All Committees
                    </Link>
                  </Button>
                </div>
              )}
            </BentoCard>

            {/* Schedule */}
            <BentoCard index={1} className="p-8">
              <div className="flex items-center mb-6">
                <div className="p-3 bg-gradient-to-br from-accent-gold/20 to-accent-gold/10 rounded-xl mr-4">
                  <Calendar className="h-6 w-6 text-accent-gold" />
                </div>
                <div>
                  <h3 className="font-display text-2xl font-bold text-foreground">
                    Schedule
                  </h3>
                  <p className="text-sm text-muted-foreground">Conference timeline</p>
                </div>
              </div>
              
              {!isRevealed(reveals.schedule.revealAt) ? (
                <div className="text-center py-8">
                  <Countdown
                    revealAt={reveals.schedule.revealAt}
                    title="Coming Soon"
                    description="Detailed schedule will be announced"
                  />
                </div>
              ) : (
                <div className="space-y-4">
                  <p className="text-muted-foreground">
                    View the complete conference schedule with session timings and activities.
                  </p>
                  <Button variant="outline" asChild>
                    <Link href="/session-3/schedule">
                      View Schedule
                    </Link>
                  </Button>
                </div>
              )}
            </BentoCard>

            {/* Venue */}
            <BentoCard index={2} className="p-8">
              <div className="flex items-center mb-6">
                <div className="p-3 bg-gradient-to-br from-accent-gold/20 to-accent-gold/10 rounded-xl mr-4">
                  <MapPin className="h-6 w-6 text-accent-gold" />
                </div>
                <div>
                  <h3 className="font-display text-2xl font-bold text-foreground">
                    Venue
                  </h3>
                  <p className="text-sm text-muted-foreground">Conference location</p>
                </div>
              </div>
              
              {!isRevealed(reveals.venue.revealAt) ? (
                <div className="text-center py-8">
                  <Countdown
                    revealAt={reveals.venue.revealAt}
                    title="Location Reveal"
                    description="Conference venue will be announced"
                  />
                </div>
              ) : (
                <div className="space-y-4">
                  {/* AIUB Venue Image */}
                  <div className="relative w-full h-48 rounded-lg overflow-hidden mb-4 group">
                    <Image
                      src="/aiub.jpg"
                      alt="American International University-Bangladesh (AIUB) Campus"
                      fill
                      className="object-cover transition-transform duration-500 group-hover:scale-105"
                      sizes="(max-width: 768px) 100vw, 50vw"
                    />
                    <div className="absolute inset-0 bg-gradient-to-t from-forest-900/80 via-transparent to-transparent" />
                    <div className="absolute bottom-3 left-3 right-3">
                      <div className="bg-forest-900/60 backdrop-blur-sm border border-accent-gold/30 rounded-lg p-3">
                        <p className="text-accent-gold font-semibold text-sm">
                          {venue.fullName}
                        </p>
                        <p className="text-forest-100 text-xs">
                          World-class venue for diplomatic excellence
                        </p>
                      </div>
                    </div>
                  </div>
                  
                  <p className="text-muted-foreground">
                    {venue.fullName} - A world-class venue for diplomatic excellence.
                  </p>
                  <Button variant="outline" asChild>
                    <Link href="/session-3/venue">
                      View Venue Details
                    </Link>
                  </Button>
                </div>
              )}
            </BentoCard>

            {/* Registration */}
            <BentoCard index={3} className="p-8 bg-gradient-to-br from-accent-gold/10 to-forest-700/10">
              <div className="flex items-center mb-6">
                <div className="p-3 bg-gradient-to-br from-accent-gold/30 to-accent-gold/20 rounded-xl mr-4">
                  <Award className="h-6 w-6 text-accent-gold" />
                </div>
                <div>
                  <h3 className="font-display text-2xl font-bold text-foreground">
                    Registration
                  </h3>
                  <p className="text-sm text-muted-foreground">Secure your spot</p>
                </div>
              </div>
              
              <div className="space-y-4">
                <p className="text-muted-foreground">
                  Secure your spot at the biggest MUN conference in South East Asia.
                </p>
                
                {/* Registration Tiers */}
                <div className="space-y-3">
                  {Object.entries(forms)
                    .filter(([key]) => ['regular', 'campusAmbassadors', 'late'].includes(key))
                    .map(([key, form]) => (
                    form.enabled && (
                      <div key={key} className="flex items-center justify-between p-3 bg-card/50 rounded-lg border border-accent-gold/20">
                        <div>
                          <div className="font-medium text-foreground">{form.title}</div>
                          <div className="text-sm text-muted-foreground">{form.description}</div>
                        </div>
                        <Button variant="thorn" size="sm" asChild>
                          <Link href="/session-3/register">
                            Register
                          </Link>
                        </Button>
                      </div>
                    )
                  ))}
                </div>
              </div>
            </BentoCard>
          </BentoGrid>
        </div>
      </section>
    </div>
  )
}
